   "sub": "家乡的味道 · 辣椒粉一撒就香",
   "region": "中餐",
   "cuisine": "赣菜",
   "kind": "素",
   "protein": "面食主食",
   "time": "20 分钟",
   "servings": "1–2 人份",
   "difficulty": "简单",
   "level": "full",
   "intro": "江西人冬天的家常：年糕片先用温水泡软，热锅炒肉、下年糕，撒辣椒粉、淋生抽老抽，最后放青菜。年糕软糯带辣，一盘就是一顿饭。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "年糕",
       "q": "300 g，切薄片"
      },
      {
       "n": "青菜（小油菜 / 白菜）",
       "q": "150 g"
      },
      {
       "n": "猪肉片",
       "q": "80 g（可选）"
      }
     ]
    },
    {
     "group": "小料",
     "items": [
      {
       "n": "蒜",
       "q": "3 瓣，切片"
      },
      {
       "n": "小米辣",
       "q": "2 个"
      },
      {
       "n": "葱",
       "q": "1 根"
      }
     ]
    },
    {
     "group": "调味",
     "items": [
      {
       "n": "辣椒粉",
       "q": "1 小勺"
      },
      {
       "n": "盐",
       "q": "适量"
      },
      {
       "n": "生抽",
       "q": "1 勺"
      },
      {
       "n": "老抽",
       "q": "半勺"
      },
      {
       "n": "食用油",
       "q": "2 勺"
      },
      {
       "n": "清水",
       "q": "少许"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "泡年糕",
     "d": "年糕切薄片，用温水泡 10 分钟（或开水焯 1 分钟）至软，捞出沥干。",
     "tip": "年糕不泡直接炒会硬芯、还容易粘锅。"
    },
    {
     "t": "炒香",
     "d": "热锅下油，肉片炒变色，加蒜片、小米辣炒香。"
    },
    {
     "t": "下年糕",
     "d": "年糕下锅翻炒，撒辣椒粉 1 小勺、盐、生抽 1 勺、老抽半勺，翻匀上色。"
    },
    {
     "t": "焖",
     "d": "沿锅边淋少许清水，盖盖焖 1 分钟，让年糕软透入味。"
    },
    {
     "t": "下青菜",
     "d": "放青菜大火翻炒至断生，撒葱花出锅。"
    }
   ],
   "tips": [
    "年糕容易粘锅，锅要热、油要够，勤翻。",
    "喜欢更辣可以把辣椒粉换成辣椒面加干辣椒段。"
   ],
