   "time": "30 分钟",
   "servings": "2–3 人份",
   "difficulty": "中等",
   "level": "full",
   "intro": "「跳水」就是鱼片下开水里汆一下——不煎不炸，肉最嫩。捞出来浇一大勺剁椒蒜蓉汁，麻辣鲜香全在汁里，嫩滑全靠那 40 秒。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "鲈鱼",
       "q": "1 条（约 750 g）"
      },
      {
       "n": "豆芽（垫底）",
       "q": "150 g"
      }
     ]
    },
    {
     "group": "上浆",
     "items": [
      {
       "n": "盐",
       "q": "1 小勺"
      },
      {
       "n": "蛋清",
       "q": "1 个"
      },
      {
       "n": "淀粉",
       "q": "1 勺"
      },
      {
       "n": "料酒",
       "q": "1 勺"
      },
      {
       "n": "白胡椒粉",
       "q": "少许"
      }
     ]
    },
    {
     "group": "浇汁",
     "items": [
      {
       "n": "小米辣",
       "q": "5 个，切碎"
      },
      {
       "n": "青椒",
       "q": "1 个，切碎"
      },
      {
       "n": "泡椒",
       "q": "2 个，切碎"
      },
      {
       "n": "蒜末",
       "q": "1 头"
      },
      {
       "n": "姜末",
       "q": "1 勺"
      },
      {
       "n": "蒸鱼豉油",
       "q": "2 勺"
      },
      {
       "n": "生抽",
       "q": "1 勺"
      },
      {
       "n": "藤椒油",
       "q": "1 勺"
      },
      {
       "n": "食用油",
       "q": "4 勺"
      },
      {
       "n": "葱花",
       "q": "适量"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "片鱼",
     "d": "鲈鱼去骨片成薄片，鱼骨鱼头留用；鱼片加盐、料酒、白胡椒、蛋清、淀粉抓匀上浆，腌 10 分钟。"
    },
    {
     "t": "垫底",
     "d": "豆芽焯水铺在盘底；鱼骨煎一下加姜片煮成奶白鱼汤，取两勺备用。"
    },
    {
     "t": "汆鱼片",
     "d": "水烧到微沸，鱼片一片片下锅，变白卷起（约 40 秒）立刻捞出，铺在豆芽上。",
     "tip": "水不能大滚，鱼片会被冲散；40 秒是嫩的极限。"
    },
    {
     "t": "调汁",
     "d": "小米辣、青椒、泡椒、蒜末、姜末放碗里，浇 4 勺烧到冒烟的热油，再加蒸鱼豉油、生抽、藤椒油和 2 勺鱼汤拌匀。"
    },
    {
     "t": "浇",
     "d": "把汁浇在鱼片上，撒葱花，静置 1 分钟入味即可。"
    }
   ],
   "tips": [
    "鱼片越薄越好，厚了容易老。",
    "藤椒油是「麻」的来源，没有就用花椒油。"
   ],
