   "servings": "2–3 人份",
   "difficulty": "中等",
   "level": "full",
   "intro": "作者用炸卤肉饭剩下的葱油来做鱼：葱油、葱花、葱酥三层葱香叠在鲈鱼上。鱼先煎到皮脆（或蒸 8 分钟），最后热葱油一泼，香气直接起来。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "鲈鱼",
       "q": "1 条（约 600 g）"
      },
      {
       "n": "小葱",
       "q": "1 大把"
      },
      {
       "n": "红葱头",
       "q": "5 个"
      }
     ]
    },
    {
     "group": "调味",
     "items": [
      {
       "n": "生抽",
       "q": "2 勺"
      },
      {
       "n": "蒸鱼豉油",
       "q": "1 勺"
      },
      {
       "n": "白糖",
       "q": "半小勺"
      },
      {
       "n": "盐",
       "q": "适量"
      },
      {
       "n": "姜",
       "q": "3 片"
      },
      {
       "n": "食用油",
       "q": "100 ml（炸葱油用）"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "处理鱼",
     "d": "鲈鱼去鳞去内脏洗净，两面划刀，用盐和姜片抹匀腌 10 分钟，擦干表面。"
    },
    {
     "t": "炸葱油",
     "d": "冷油下葱白段和红葱头片，小火慢炸到金黄酥脆，捞出葱酥留用，油过滤成葱油。",
     "tip": "小火冷油下锅，葱才香不糊。"
    },
    {
     "t": "煎鱼（或蒸）",
     "d": "锅烧热，用 1 勺葱油把鱼两面煎到金黄定型；想更嫩就上锅蒸 8 分钟。"
    },
    {
     "t": "调汁",
     "d": "生抽 2 勺、蒸鱼豉油 1 勺、糖半小勺，加 2 勺热水调匀，淋在鱼上。"
    },
    {
     "t": "泼油",
     "d": "葱油烧到冒烟，泼在鱼身和葱花上。"
    },
    {
     "t": "撒葱酥",
     "d": "撒预留的葱酥和大量葱花，趁热吃。"
    }
   ],
   "tips": [
    "葱油一次可以多炸，拌面拌饭都好用。",
    "鲈鱼胶质偏薄，换石斑、多宝鱼口感更好——作者自己的建议。"
   ],
