   "intro": "香蕉烤过之后甜度会翻倍、带焦糖香，压成泥铺在杯底，加泡软的燕麦和燕麦奶，最后淋一份浓缩。喝前搅一搅，底下是糯叽叽的燕麦和香蕉泥。",
