     "t": "烤香蕉",
     "d": "香蕉带皮放进烤箱 200℃ 烤 15 分钟，表皮发黑、果肉变软出焦糖香即可。",
     "tip": "带皮烤能保住水分和甜味，别剥皮烤。"
