   "id": "6aaa3c34000000002a02d6e6",
   "name": "冻香蕉拿铁",
   "en": "Frozen Banana Latte",
   "sub": "被低估的食材：冻香蕉当冰淇淋用",
   "region": "西餐",
   "cuisine": "饮品·调酒",
   "kind": "甜饮",
   "protein": "饮品",
   "time": "10 分钟（需提前冷冻）",
   "servings": "1 杯",
   "difficulty": "简单",
   "level": "full",
   "intro": "香蕉冷冻后打成泥，质地和冰淇淋一模一样，还自带甜味——不用加糖、不用加冰，铺在杯底再淋咖啡，就是一杯「香蕉冰淇淋拿铁」。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "熟香蕉",
       "q": "1 根（提前冷冻 4 小时以上）"
      },
      {
       "n": "牛奶 / 燕麦奶",
       "q": "150 ml（打香蕉泥用 30 ml）"
      },
      {
       "n": "浓缩咖啡",
       "q": "1 份（或速溶黑咖啡 80 ml）"
      }
     ]
    },
    {
     "group": "可选",
     "items": [
      {
       "n": "蜂蜜 / 枫糖",
       "q": "少许（香蕉够甜可不加）"
      },
      {
       "n": "肉桂粉、可可粉",
       "q": "少许"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "冻香蕉",
     "d": "香蕉剥皮切段，装保鲜袋冷冻 4 小时以上（可一次多冻几根，随用随取）。"
    },
    {
     "t": "打泥",
     "d": "冷冻香蕉段 + 30 ml 牛奶放进料理机，打 30–40 秒至顺滑浓稠的泥状。",
     "tip": "牛奶别一次加多，加多了就成奶昔、立不住了。"
    },
    {
     "t": "铺杯底",
     "d": "把香蕉泥厚厚地铺在杯底，抹平。"
    },
    {
     "t": "倒奶",
     "d": "倒入剩下的 120 ml 冰牛奶。"
    },
    {
     "t": "淋咖啡",
     "d": "最后慢慢淋入浓缩咖啡，表面会分层；可撒肉桂粉。"
    }
   ],
   "tips": [
    "香蕉要选皮上有黑点的熟蕉，冷冻后甜度更高。",
    "喝前用勺子搅一下，让香蕉泥和咖啡混匀。"
   ],
