   "level": "full",
   "intro": "客家人坐月子必喝的一锅：老姜带皮拍扁炒香，鸡块下锅炒到微黄，倒客家黄酒（娘酒）加水慢煮，最后卧一个煎蛋、撒把枸杞。汤甜、酒香、姜辣，秋冬喝最舒服。",
