   "difficulty": "中等",
   "level": "full",
   "intro": "作者把三个关键点写得很清楚：蹄髈先火烤去毛、冷水加姜片料酒焯 10 分钟去腥；砂锅用开水炖，加山楂和姜；黄豆用加盐的水泡 3 小时（或电饭煲煮 30 分钟）再连豆汤倒进去。最后大火滚 10 分钟，油脂乳化，汤才浓白。",
