   "name": "藿香鱼",
   "en": "Braised Fish with Agastache",
   "sub": "夏天独有的味道 · 猪油起锅更香",
   "region": "中餐",
   "cuisine": "川菜",
   "kind": "荤",
   "protein": "鱼类",
   "time": "35 分钟",
   "servings": "2–3 人份",
   "difficulty": "中等",
   "level": "full",
   "intro": "川南夏天的家常味：鱼先煎到两面金黄，再用猪油、豆瓣、泡椒、姜蒜烧入味，起锅前下一大把藿香叶。藿香的清苦配鱼鲜，是这道菜的灵魂。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "鲫鱼 / 鲈鱼",
       "q": "1 条（约 600 g）"
      },
      {
       "n": "藿香叶",
       "q": "1 大把（约 30 g）"
      }
     ]
    },
    {
     "group": "配料",
     "items": [
      {
       "n": "猪油",
       "q": "1 勺"
      },
      {
       "n": "菜籽油",
       "q": "2 勺"
      },
      {
       "n": "郫县豆瓣",
       "q": "1 勺"
      },
      {
       "n": "泡椒",
       "q": "2 个"
      },
      {
       "n": "姜末、蒜末",
       "q": "各 1 勺"
      },
      {
       "n": "花椒",
       "q": "1 小勺"
      },
      {
       "n": "葱花",
       "q": "适量"
      }
     ]
    },
    {
     "group": "调味",
     "items": [
      {
       "n": "料酒",
       "q": "2 勺"
      },
      {
       "n": "生抽",
       "q": "1 勺"
      },
      {
       "n": "白糖",
       "q": "1 小勺"
      },
      {
       "n": "盐",
       "q": "适量"
      },
      {
       "n": "清水",
       "q": "300 ml"
      },
      {
       "n": "水淀粉",
       "q": "少许"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "处理鱼",
     "d": "鱼去鳞去内脏洗净，两面各划几刀，用盐和料酒抹匀腌 10 分钟，擦干表面。"
    },
    {
     "t": "煎鱼",
     "d": "锅烧热，下猪油和菜籽油，鱼下锅煎到两面金黄定型，盛出。",
     "tip": "猪油起锅是这道菜香的来源，别全用植物油。"
    },
    {
     "t": "炒料",
     "d": "用锅里的油炒香豆瓣、泡椒、姜蒜末和花椒，炒出红油。"
    },
    {
     "t": "烧",
     "d": "加 300 ml 清水、料酒、生抽、糖，煮开后放回鱼，中小火烧 8–10 分钟，中途把汤汁浇在鱼身上。"
    },
    {
     "t": "下藿香",
     "d": "收汁到剩一半时，把藿香叶撕碎撒进去，煮 1 分钟出香。",
     "tip": "藿香最后放，久煮会失去清香。"
    },
    {
     "t": "出锅",
     "d": "淋少许水淀粉收亮，撒葱花，连汁装盘。"
    }
   ],
   "tips": [
    "买不到藿香，可用紫苏或九层塔替代，风味略有不同。",
    "鱼不要翻来翻去，用浇汁的方式入味。"
   ],
