   "level": "full",
   "intro": "作者把米其林餐厅 268 的鹅肝吐司拆成了家常版：鹅肝切片 2 片、厚吐司 2 片、红酒 2 勺 + 蜂蜜 1 勺收汁、黄油 10 g 煎、无花果和蓝莓摆盘。四个法式小技巧都写全了。",
