   "level": "full",
   "intro": "全程不用油、牛肉也不腌：水开下肉片，变色就捞，靠一碗柠檬蘸水把味道撑起来。蒜末、小米辣、白芝麻、香菜加柠檬，酸辣清爽，身材管理期也能放心吃。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "牛里脊（或肥牛片）",
       "q": "300 g，切薄片"
      },
      {
       "n": "柠檬",
       "q": "1–2 个"
      }
     ]
    },
    {
     "group": "蘸水",
     "items": [
      {
       "n": "蒜末",
       "q": "4 瓣"
      },
      {
       "n": "小米辣",
       "q": "3 个，切碎"
      },
      {
       "n": "白芝麻",
       "q": "1 勺（熟）"
      },
      {
       "n": "香菜",
       "q": "1 小把，切碎"
      },
      {
       "n": "生抽",
       "q": "2 勺"
      },
      {
       "n": "鱼露",
       "q": "半勺（可选）"
      },
      {
       "n": "白糖",
       "q": "半小勺"
      },
      {
       "n": "盐",
       "q": "少许"
      }
     ]
    },
    {
     "group": "汆肉",
     "items": [
      {
       "n": "姜片",
       "q": "3 片"
      },
      {
       "n": "料酒",
       "q": "1 勺"
      },
      {
       "n": "清水",
       "q": "约 1 L"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "切牛肉",
     "d": "牛里脊逆纹切薄片（或直接用肥牛片），不用腌。"
    },
    {
     "t": "烧水",
     "d": "锅中加水和姜片、料酒烧开，转小火让水面微微冒泡。",
     "tip": "水不要大滚，滚太厉害肉片会老。"
    },
    {
     "t": "汆",
     "d": "牛肉片一片片下锅，变色卷起立即捞出（约 30–40 秒），过一下凉开水更紧实。"
    },
    {
     "t": "调蘸水",
     "d": "蒜末、小米辣、白芝麻、香菜放碗里，加生抽 2 勺、鱼露半勺、糖半小勺、少许盐。"
    },
    {
     "t": "加柠檬",
     "d": "挤入柠檬汁、放两片柠檬，拌匀即可。"
    },
    {
     "t": "上桌",
     "d": "牛肉片蘸着吃，或直接把蘸水浇在牛肉上。"
    }
   ],
   "tips": [
    "柠檬汁现挤现吃，放久了会发苦。",
    "喜欢更酸可以加一个青柠，香气比黄柠檬更足。"
   ],
