   "difficulty": "简单",
   "level": "full",
   "intro": "口蘑和火腿，两样东西十分钟出锅。作者三条避坑特别实用：蘑菇用湿布擦不水洗、一定要炒到出完水变金黄、**先给蘑菇调味再下火腿**（火腿本身很咸）。",
