   "protein": "饮品",
   "time": "浸泡 3–7 天",
   "servings": "1 瓶（约 500 ml）",
   "difficulty": "简单",
   "level": "full",
   "intro": "把香水柠檬和柠檬叶泡进金酒里，几天后得到一瓶自带柑橘香和草本尾韵的风味金酒。直接兑汤力水就是金汤力，兑柠檬汁就是吉姆雷特。",
   "ingredients": [
    {
     "group": "浸泡",
     "items": [
      {
       "n": "金酒（London Dry）",
       "q": "500 ml"
      },
      {
       "n": "香水柠檬",
       "q": "2 个"
      },
      {
       "n": "泰国柠檬叶（kaffir lime）",
       "q": "6 片"
      }
     ]
    },
    {
     "group": "出品 · 金汤力",
     "items": [
      {
       "n": "风味金酒",
       "q": "45 ml"
      },
      {
       "n": "汤力水",
       "q": "150 ml"
      },
      {
       "n": "冰块",
       "q": "满杯"
      }
     ]
    },
    {
     "group": "出品 · 吉姆雷特",
     "items": [
      {
       "n": "风味金酒",
       "q": "60 ml"
      },
      {
       "n": "鲜柠檬汁",
       "q": "20 ml"
      },
      {
       "n": "糖浆",
       "q": "10 ml"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "处理柠檬",
     "d": "香水柠檬用盐搓洗表皮、冲净擦干，切薄片并**去掉籽**（籽会发苦）。"
    },
    {
     "t": "处理柠檬叶",
     "d": "柠檬叶撕开或剪两刀，让香气更容易释放。"
    },
    {
     "t": "浸泡",
     "d": "柠檬片、柠檬叶放进干净玻璃瓶，倒满金酒，密封放阴凉避光处 3–7 天，每天摇一摇。",
     "tip": "泡 3 天果香最清亮，泡到 7 天草本味更重，按口味取。"
    },
    {
     "t": "过滤",
     "d": "用滤纸或细筛过滤掉果片和叶子，装瓶冷藏保存 1 个月。"
    },
    {
     "t": "金汤力",
     "d": "杯中满冰，倒 45 ml 风味金酒，汤力水补满，放一片香水柠檬。"
    },
    {
     "t": "吉姆雷特",
     "d": "60 ml 风味金酒 + 20 ml 鲜柠檬汁 + 10 ml 糖浆，加冰摇匀，滤入冰镇酒杯。"
    }
   ],
   "tips": [
    "金酒选杜松子味清爽的，别用风味太重的。",
    "浸泡别超过两周，久了柠檬皮的白瓤会发苦。"
   ],
