   "intro": "河粉的灵魂是汤：牛尾和牛腱先焯，洋葱、姜、红葱头烤到焦香，八角桂皮等香料干锅焙过再下锅，小火慢炖 2–3 小时，最后用鱼露调味。配料按越南吃法配齐。",
