   "intro": "换季嗓干的时候最合适。作者把材料写得很清楚：雪梨 2 个（推荐砀山梨或香梨）、黄冰糖、水 800–1000 ml，可加红枣、枸杞或川贝。炖到梨块透明软烂，汤汁清润。",
