   "servings": "2–3 人份",
   "difficulty": "中等",
   "level": "full",
   "intro": "「桑拿」就是用旺火蒸汽把腌好的鸡件快速蒸熟：鸡件摊平、水大开、盖盖 4–5 分钟，肉刚熟就起锅——这就是嫩滑鲜甜的全部秘密。锅里同时煮一锅汤，一鸡两吃。",
   "ingredients": [
    {
     "group": "主料",
     "items": [
      {
       "n": "清远鸡（或三黄鸡）",
       "q": "半只（约 600 g），斩小块"
      },
      {
       "n": "虫草花（可选）",
       "q": "1 小把"
      }
     ]
    },
    {
     "group": "腌鸡",
     "items": [
      {
       "n": "盐",
       "q": "1 小勺"
      },
      {
       "n": "白糖",
       "q": "半小勺"
      },
      {
       "n": "生粉",
       "q": "2 小勺"
      },
      {
       "n": "花生油",
       "q": "1 勺"
      },
      {
       "n": "姜丝",
       "q": "少许"
      }
     ]
    },
    {
     "group": "蘸料 · 锅底",
     "items": [
      {
       "n": "姜末、葱花",
       "q": "各 2 勺"
      },
      {
       "n": "热油",
       "q": "2 勺"
      },
      {
       "n": "生抽",
       "q": "1 勺"
      },
      {
       "n": "清水（锅底）",
       "q": "适量"
      }
     ]
    }
   ],
   "steps": [
    {
     "t": "斩件腌制",
     "d": "鸡斩成 2 cm 小块，加盐、糖、生粉、花生油和姜丝抓匀，腌 15 分钟。",
     "tip": "生粉锁水、油封表面，是「嫩滑」的关键。"
    },
    {
     "t": "铺盘",
     "d": "鸡件平铺在盘子里，不要堆叠，下面可垫虫草花或姜片。"
    },
    {
     "t": "烧水",
     "d": "锅底加清水烧到大滚（可放几块鸡骨、姜片煮汤）。"
    },
    {
     "t": "蒸",
     "d": "盘子放进蒸架，盖严，旺火蒸 4–5 分钟，鸡件变白、骨头不带血即熟。",
     "tip": "火力一定要猛、时间一定要短，蒸汽足才叫「桑拿」。"
    },
    {
     "t": "蘸料",
     "d": "姜末葱花加 2 勺烧到冒烟的热油，再调 1 勺生抽。"
    },
    {
     "t": "上桌",
     "d": "趁热吃鸡，锅底的汤加盐就是一碗清鸡汤。"
    }
   ],
   "tips": [
    "鸡斩小一点，4 分钟能熟透，块大就要延长时间。",
    "不用加酱油腌，要的就是鸡肉本身的鲜甜。"
   ],
